package com.dreamcore.game

/** Individually authored situations and evidence for all 61 inherited worlds. */
object DreamStories33 {
 data class Story(val title:String,val situation:String,val clue:String,val request:String,val answer:String,val keep:String,val rule:String)
 val stories=mapOf(
  DreamHorizons36.SUNSET to Story("El peldaño que flota","Una puerta conserva la luz del último sol.","La escalera termina donde el cielo comienza a reflejarse.","Recuerda la forma del horizonte.","El último peldaño conserva tu sombra.","El cielo recuerda un pequeño salto.","memory"),
  DreamHorizons36.RED to Story("El peso del gigante","Un planeta ocupa casi todo el cielo.","Sus bandas cambian lentamente sobre la piedra roja.","Escucha el aire entre las agujas.","El valle conserva un intervalo de silencio.","Una nube guarda tu respiración.","sound"),
  DreamHorizons36.BLUE to Story("El regreso de la altura","Una roca se sostiene sobre el reflejo.","Al cerrar los ojos la altura vuelve a encontrarte.","Observa el mismo cielo en el agua.","El océano conserva la dirección de tu mirada.","La roca reconoce tu regreso.","memory"),
  DreamRainward34.ID to Story("El último turno","Todos los pisos conservan una luz, pero nadie ha fichado su salida.","El teléfono sin línea reproduce una respiración detrás de la puerta roja.","Lleva la ficha del turno hasta el reloj de la plaza y escucha lo que falta.","El inquilino deja de esperar una voz que no iba a volver.","Conservas la ficha: otro turno queda despierto en la ciudad.","sound"),
  "dream_01" to Story("Un reloj sin constructor","El reloj del Umbral tiene una firma borrada.","La carta llama Alma a la persona que guardaba las llaves.","Encaja la llave que alguien dejó junto al reloj.","El reloj recupera un latido. Un nombre vuelve al archivo.","Conservas la llave; el reloj aprende tu silencio.","read"),
  "dream_02" to Story("La toalla que nunca se seca","Una toalla conserva agua aunque la piscina esté quieta.","Su etiqueta dibuja una biblioteca bajo tres ondas.","Escucha el agua y deja la toalla junto a su marca.","Las ondas revelan el sello del plano de la biblioteca.","La tela gotea dentro de tu equipaje.","sound"),
  "dream_03" to Story("Correo hacia abajo","Una carta está dirigida al fondo del abismo.","La dirección coincide con una casa que todavía no ha caído.","Devuelve la carta a la pequeña ranura.","Una ventana del fondo permanece encendida.","La carta conserva el olor de una casa cerrada.","return"),
  "dream_04" to Story("El jardinero ausente","Una maceta recibe lluvia desde una ventana cerrada.","Hay dos sombras donde solo queda una planta.","Compara el jardín con su recuerdo.","Reconoces dónde estuvo la segunda maceta.","Conservas una hoja que no proyecta sombra.","memory"),
  "dream_05" to Story("La lámpara prestada","Una casa espera la lámpara que alguien retiró.","La etiqueta dice: «Para que encuentre el camino de vuelta».","Devuelve la lámpara al alféizar.","La casa vuelve a iluminarse y su visitante cambia de lugar.","La luz te acompaña; la casa queda esperando.","return"),
  "dream_06" to Story("La voz bajo la marea","Una caracola vibra cuando la criatura se aproxima.","La voz dice que el cielo también tiene un suelo.","Escucha su respuesta sin mover la caracola.","La marea conserva un nuevo intervalo en la grabación.","El mar repite tu último paso.","sound"),
  "dream_07" to Story("La silla del otro lado","Una silla ocupa dos posiciones en dos recuerdos.","En uno de ellos hay una taza todavía caliente.","Reconoce qué lado de la puerta está habitado.","Dejas sitio para quien falta.","La silla conserva tu forma.","memory"),
  "dream_08" to Story("El billete de llegada","El andén guarda un billete que nunca se perforó.","La estación solo anota las llegadas, no las partidas.","Coloca el billete junto al reloj.","El horario incorpora un nombre que reconoces.","El tren conserva un asiento vacío.","return"),
  "dream_09" to Story("Las piezas del huésped","Falta una pieza blanca en una partida detenida.","El tablero repite la distribución de las ventanas del pueblo.","Devuelve la pieza al lugar de la casa apagada.","El tablero deja una casilla libre para otro viajero.","La pieza pesa más al alejarte.","return"),
  "dream_10" to Story("La tubería que canta","Una tubería devuelve tres gotas desiguales.","Un golpe, dos golpes y una pausa: el ritmo de una puerta.","Observa la lámpara antes de responder.","Una ducha deja de llorar cuando reconoces su ritmo.","La tubería aprende un silencio distinto.","rhythm"),
  "dream_11" to Story("El turno que falta","Una llave de hotel marca el turno de una oficina.","Detrás de la puerta de servicio se oye un teclado.","Escucha y devuelve la llave del turno ausente.","Hotel y oficina reconocen la misma puerta.","La oficina sigue trabajando para una habitación vacía.","sound"),
  "dream_12" to Story("La última curva","Una señal conserva la sombra de un automóvil ausente.","El conductor dibujó una salida que solo existía al amanecer.","Compara la señal con la carretera recordada.","El dibujo recupera una curva que habías pasado por alto.","La flecha vuelve a señalar tu llegada.","memory"),
  "dream_13" to Story("Una entrada bajo las lágrimas","La taquilla guarda una pulsera de otro verano.","Su color coincide con una puerta que nunca se abre al público.","Devuelve la pulsera a la taquilla.","Una lágrima deja de caer durante un instante.","La pulsera conserva el calor de otra mano.","return"),
  "dream_14" to Story("La órbita del recreo","Un planeta pequeño repite el movimiento de una canica.","La canica tiene dibujado un anillo que no se ve a simple vista.","Observa el ritmo de su pequeño reloj.","La órbita deja un espacio para la canica perdida.","El anillo desaparece cuando intentas guardarlo.","rhythm"),
  "dream_15" to Story("El último nombre del recreo","Una lista de asistencia tiene una línea borrada.","Alma figura como encargada de devolver los objetos olvidados.","Reconstruye el nombre con las marcas del recuerdo.","La lista deja de pasar páginas sola.","Una silla queda orientada hacia la puerta.","memory"),
  "dark_01" to Story("La corona del durmiente","Una corona fue dejada de espaldas a las lunas.","Su interior muestra el mismo sello del Umbral.","Gira la corona hacia quien la dejó.","Las ruinas reconocen una antigua promesa.","La corona enfría la piedra donde estuvo.","return"),
  "dark_02" to Story("El herbario de la reina","Una flor seca conserva polen azul bajo la nieve.","El dibujo de la flor cambia en cada época de la ruina.","Compara el herbario con su recuerdo.","Encuentras el jardín que había antes del trono.","La flor se cierra sobre el nombre borrado.","memory"),
  "pocket_laundry" to Story("Lavado de recuerdos","Una lavadora sigue girando con una camisa dentro.","La etiqueta lleva la misma marca de agua de las piscinas.","Escucha el tambor antes de abrir la pequeña compuerta.","Una camisa seca vuelve al estante de su dueña.","El tambor continúa su turno sin ropa.","sound"),
  "pocket_train" to Story("El asiento reservado","Un boleto reserva un asiento de otro vagón.","El número coincide con el reloj del refugio.","Devuelve el boleto al bolsillo del asiento.","Una pasajera reconoce la reserva durante el túnel.","El asiento permanece vacío a tu lado.","return"),
  "pocket_dawn" to Story("La persiana de las seis","Un reloj no alcanza a terminar su última vuelta.","Una raya de luz marca dónde estuvo antes una ventana.","Compara la habitación con su amanecer anterior.","La persiana deja entrar un minuto que faltaba.","El minuto queda guardado en tu reloj.","memory"),
  "pocket_tower" to Story("El telescopio de la torre","Una lente mira hacia una escalera que nadie ve.","Su funda muestra dos escalones borrados por la lluvia.","Escucha el eco que vuelve desde lo alto.","La torre devuelve un paso que no era el tuyo.","La lente guarda una escalera más larga.","sound"),
  "pocket_cloudbed" to Story("El peso de una noche","Una almohada conserva una hendidura reciente.","El bordado muestra una casa que no aparece en el cielo.","Reconoce la casa al superponer su recuerdo.","La cama deja de hundirse en el lado vacío.","La hendidura conserva tu respiración.","memory"),
  "pocket_refuge" to Story("La taza junto a la puerta","Alguien utiliza una taza que no habías dejado servida.","Una costura blanca y un broche de reloj identifican a la visitante.","Decide qué lugar dejas para quien regresa.","El refugio aprende a recibir una visita.","La visitante espera al otro lado de la puerta.","read"),
  "photo_house" to Story("Antes de que se cerrara la casa","La fotografía conserva una ventana que ya no existe.","Dos épocas comparten la marca de un marco.","Superpón el recuerdo y reconoce la abertura.","La casa devuelve una habitación que faltaba.","El marco conserva una pared donde hubo una puerta.","memory"),
  "photo_sea" to Story("La marea detenida","Una fotografía conserva una ola que todavía no cayó.","En la espuma aparece la marca de la caracola.","Compara la orilla con su recuerdo.","La ola recupera el sonido que le faltaba.","La espuma conserva el borde de una carta.","memory"),
  "photo_window" to Story("La sombra del cristal","El cristal refleja una lámpara encendida en otro año.","Su interruptor está en una pared que cambió de sitio.","Reconoce la pared de la lámpara en el recuerdo.","El cristal deja pasar una luz antigua.","La lámpara queda encendida dentro de la imagen.","memory"),
  "photo_planet" to Story("El anillo sin planeta","Una fotografía conserva un anillo y ningún centro.","El telescopio dibuja el mismo círculo incompleto.","Superpón ambas épocas para reconocer su órbita.","El anillo recupera una sombra que lo acompañaba.","El centro queda vacío al cerrar el álbum.","memory"),
  "pocket_letter" to Story("El destinatario del cartero","Una carta no tiene nombre, solo la forma de una casa.","La firma está en la parte interior del sobre.","Devuelve el sobre a la dirección que reconoce.","El cartero deja una carta más pequeña junto al marco.","La casa cambia de número en tu recuerdo.","return"),
  "pocket_gravity" to Story("La habitación girada","Una mesa dejó sus marcas en la pared.","Las cuatro marcas siguen perteneciendo al mismo suelo.","Compara las dos posiciones de la habitación.","Reconoces qué pared sostuvo la primera taza.","Las marcas permanecen orientadas hacia ti.","memory"),
  "echo_01" to Story("La casa que perdió su vertical","Una puerta conserva la inclinación de un día anterior.","La sombra está derecha aunque el marco se haya inclinado.","Superpón el recuerdo de su umbral.","La puerta conserva sitio para una sombra distinta.","El marco continúa su inclinación hacia el vacío.","memory"),
  "echo_02" to Story("La última proyección","Una entrada de cine tiene impreso el nombre de una calle.","La pantalla conserva una avenida que aparece en las antenas.","Devuelve la entrada a su butaca.","La proyección reconoce una puerta fuera de la sala.","La butaca reserva otra función para ti.","return"),
  "echo_03" to Story("El turno del agua","Una ducha funciona para un huésped que no está.","Su tubería lleva el sello del hotel de las nubes.","Escucha a quién le corresponde el siguiente turno.","La ducha devuelve una voz desde el valle.","El agua continúa cayendo para nadie.","sound"),
  "echo_04" to Story("La casa que llegó al reflejo","El agua muestra una ventana más que la casa.","La ventana adicional tiene la lámpara del pueblo.","Compara la casa y su época reflejada.","Reconoces una habitación que la casa había olvidado.","El agua conserva la habitación para otra visita.","memory"),
  "echo_05" to Story("La espora del canal","Un hongo conserva el dibujo de una llave.","La llave se reconoce por el ojo grabado en su arco.","Devuelve la espora a la grieta de donde salió.","Un ojo del canal deja de seguir tus pasos.","La espora dibuja una grieta dentro del bolsillo.","return"),
  "echo_06" to Story("La nube que esperó","Una libreta registra el paso de una única nube.","El último dibujo termina con el nombre de Alma.","Escucha el aire mientras la nube cubre la señal.","La libreta registra un paso que faltaba.","La página conserva una sombra quieta.","sound"),
  "echo_07" to Story("La cuenta del último cliente","Una gasolinera dejó una cuenta sin cobrar.","El recibo tiene la hora de una estación apagada.","Devuelve el recibo al cajón del mostrador.","La luz del mostrador vuelve a responder.","La cuenta queda abierta a tu nombre.","return"),
  "echo_08" to Story("El color del vecino","Una casa proyecta el color que corresponde a otra.","El dibujo del barrio conserva la distribución antigua.","Reconoce los dos colores en el recuerdo.","Las sombras recuperan un patio compartido.","Tu sombra conserva un color prestado.","memory"),
  "echo_09" to Story("La silla que se reservó","Una silla conserva polvo salvo en uno de sus brazos.","El respaldo lleva cosida una inicial y un pequeño reloj.","Escucha quién vuelve a ocuparla.","El pasillo devuelve un roce de tela desde el fondo.","La silla queda orientada hacia tu partida.","sound"),
  "echo_10" to Story("El piso que no se anotó","Un plano cuenta un piso menos que el edificio.","El número ausente aparece en el bolsillo de una túnica.","Compara las dos versiones del plano.","Encuentras el corredor que unió ambos pisos.","El plano conserva una escalera sin nombre.","memory"),
  "echo_11" to Story("El turno de los monitores","Un monitor permanece tibio mientras los demás están apagados.","Su horario coincide con la llave del hotel.","Escucha el teclado del turno ausente.","Una mesa deja de esperar al mismo empleado.","El monitor guarda un escritorio dentro de la pantalla.","sound"),
  "preview_eyes" to Story("La mirada que descansa","Un ojo del campo conserva una pestaña distinta.","La pestaña señala un lugar donde la hierba sigue intacta.","Reconoce el campo antes de que aprendiera a mirar.","El ojo descansa mientras conservas su historia.","La hierba aprende la forma de tu paso.","memory"),
  "dream_rose_island" to Story("La casa sobre el océano","Una postal muestra la casa antes de que el mar la rodeara.","La línea del horizonte coincide con una marca en su puerta.","Devuelve la postal a la caja del jardín.","La casa conserva una dirección para quien vuelve.","El océano guarda la dirección en su reflejo.","return"),
  "backrooms_01" to Story("El turno del fluorescente","Una placa de mantenimiento tiene un nombre tachado.","La lámpara estable marca uno, dos y silencio.","Observa su ritmo antes de registrar el turno.","Una sala deja de repetir su número.","El zumbido añade una sílaba a tu nombre.","rhythm"),
  "dream_sky_openings" to Story("La abertura equivocada","Una señal dibuja una ventana que parece cielo.","El marco correcto conserva el sello de las cartas.","Compara el dibujo con la abertura recordada.","La señal vuelve a orientar a otro viajero.","El cielo conserva una abertura más pequeña.","memory"),
  "dream_cloud_castle" to Story("El ascensor sin destino","Un botón del castillo está gastado por una sola mano.","La mano dejó una marca de polen junto al botón.","Escucha la respuesta del ascensor vacío.","El botón reconoce el camino hacia las flores.","El ascensor conserva el ruido de tu llegada.","sound"),
  "dream_flower_city" to Story("La flor del andén","Una flor crece entre dos rieles.","El billete tiene dibujada esa flor en lugar de un número.","Devuelve el billete a la pequeña marquesina.","El andén conserva un destino para la próxima partida.","La flor sigue esperando su tren.","return"),
  "dream_grass_fissures" to Story("El puente de la grieta","Una tabla muestra huellas que terminan antes de la casa.","Las marcas antiguas continúan en otra época del puente.","Superpón las dos orillas.","Reconoces quién cruzó antes que tú.","La grieta conserva el final de las huellas.","memory"),
  "pocket_call_house" to Story("La llamada archivada","Un teléfono conserva una llamada sin duración.","La voz dice que Alma nunca dejó de ordenar las cartas.","Escucha la segunda mitad de la llamada.","El teléfono devuelve una despedida que faltaba.","La llamada queda esperando tu nombre.","sound"),
  "dark_03" to Story("El nombre bajo la nieve","Una señal conserva letras bajo la escarcha.","La nieve repite el sello de la corona del durmiente.","Devuelve la insignia a la señal.","Una ventana roja conserva un nombre humano.","La señal conserva la silueta de tu mano.","return"),
  "dark_04" to Story("La piedra del castillo pálido","Una piedra fue retirada para escuchar el exterior.","La marca de la piedra aparece en un plano del archivo.","Reconoce el muro en su época anterior.","El castillo recupera una abertura que respiraba.","El muro conserva el hueco de una pregunta.","memory"),
  "dream_sanctuary_clouds" to Story("El testigo entre nubes","Una pluma permanece quieta cuando el cielo se mueve.","La pluma tiene la misma costura que la túnica de la visitante.","Escucha lo que vibra durante el paso del gigante.","La pluma vuelve a acompañar a su sombra.","La nube conserva un pequeño espacio vacío.","sound"),
  "dream_library30" to Story("El índice del constructor","Un libro no contiene planos de edificios, sino decisiones.","La marca de agua de las piscinas permite leer la firma de Alma.","Relaciona la marca de agua con el plano.","Reconoces a la archivista y la puerta del depósito.","El plano conserva la marca que falta en las piscinas.","read"),
  "dream_fair30" to Story("La vuelta del carrusel","Una montura conserva un boleto bajo la pintura.","El boleto fue emitido para dos personas y una sola vuelta.","Devuelve el boleto a la caja de la feria.","El carrusel conserva un asiento para la visitante.","El motor sigue contando una vuelta pendiente.","return"),
  "dream_station30" to Story("La llegada sin cartel","El reloj de una estación no tiene agujas.","El nombre borrado está escrito en la parte de atrás del horario.","Compara el horario con su recuerdo.","La estación registra una llegada de Alma.","El andén conserva el horario sin destino.","memory"),
  "horror_atrium32" to Story("La voz del coro","Una túnica conserva una costura que no pertenece al coro.","Entre dos notas se escucha el ritmo del archivo.","Escucha la nota que responde desde el pasillo.","El coro devuelve una voz a la visitante.","La nota permanece guardada en la piedra.","sound"),
  "horror_garden32" to Story("El registro de las antenas","La estructura del ojo registra direcciones, no imágenes.","Una antena apunta a la butaca del último cine.","Observa el ritmo de su pequeño reloj.","El registro reconoce una proyección que estuvo mirando.","Una antena conserva la dirección de tu espalda.","rhythm"),
  "horror_road32" to Story("El farol del testigo","Un farol ilumina una huella que no avanza.","La huella tiene la misma forma que un ala plegada.","Compara la avenida antes de la llegada de la figura.","La huella deja sitio para un paso distinto.","El farol conserva una sombra más alta.","memory"),
  "horror_forest32" to Story("La hora del sol vacío","Un cuadrante registra una hora sin luz.","Las astas de la figura repiten el dibujo de las ramas del plano.","Devuelve el pequeño disco al cuadrante.","El bosque conserva una hora para la mañana.","El sol guarda el hueco de tu reflejo.","return"),
  "horror_screens32" to Story("Una señal entre flores","Un monitor muestra una flor que crece a su espalda.","El vagón conserva el mismo sonido que las tuberías del valle.","Escucha la señal que vuelve desde el vagón.","La pantalla deja una flor fuera de su marco.","La señal conserva un jardín que no has visitado.","sound"),
  "horror_house32" to Story("El hilo de la casa","El cable vibra con el peso de un objeto ausente.","La caja del jardín conserva el dibujo de una llave del refugio.","Devuelve el contrapeso a la caja.","La isla conserva un lugar para otra visita.","El hilo aprende el peso de tu secreto.","return"),
  "horror_pool32" to Story("El ojo de la orilla","Un ojo del agua mira hacia una escalera vacía.","En su reflejo, alguien acaba de salir de la piscina.","Compara las dos orillas del recuerdo.","La escalera recupera una huella húmeda.","El agua conserva la mirada de quien salió.","memory")
 )
 fun get(id:String)=stories[id]?:Story("El depósito de las voces","Una voz quedó guardada en el depósito.","La archivista conoce la segunda mano de la cerradura.","Recupera el cilindro y escucha la respuesta.","El archivo reconoce dos voces.","El archivo conserva su silencio.","read")
}
